import {filterRooms,validateBooking,bookingSummary} from './logic.mjs';

const rooms=[
 {id:'forest',name:'Forest Cabin',subtitle:'Một căn nhà nhỏ, cả khu rừng riêng.',image:'cabin',gallery:['cabin','room','trail'],capacity:2,size:35,price:1800000,tag:'CHO HAI NGƯỜI',description:'Nép dưới tán cây, nơi ánh sáng len qua khung cửa và tiếng chim thay cho chuông báo thức.',long:'Một căn cabin dành cho những ngày bạn muốn tạm gác lại mọi lịch trình. Mở cửa ra hiên gỗ, pha một tách trà và để khu rừng dẫn dắt nhịp ngày mới. Không gian được hình dung với chất liệu mộc, chăn vải mềm và những ô cửa thật rộng.',amenities:['Giường đôi 1,8 m','Hiên gỗ riêng','Bữa sáng cho 2 người','Phòng tắm riêng','Wi-Fi miễn phí','Ấm trà & cà phê']},
 {id:'hill',name:'Hilltop Suite',subtitle:'Thức dậy giữa những tầng xanh.',image:'room',gallery:['room','suite','forest'],capacity:4,size:55,price:2800000,tag:'TẦM NHÌN RỘNG MỞ',description:'Căn suite ngập ánh sáng, khoảng hiên rộng và những buổi sớm thật chậm bên người thương.',long:'Với góc nhìn mở về những triền cây, Hilltop Suite dành nhiều diện tích cho sự thảnh thơi. Một phòng ngủ rộng, khu sinh hoạt nhỏ và hiên riêng để ngắm nắng đổi màu qua từng giờ. Phù hợp cho cặp đôi hoặc gia đình nhỏ cùng tận hưởng kỳ nghỉ.',amenities:['Giường đôi & sofa bed','Hiên ngắm rừng','Bữa sáng cho 4 người','Bồn tắm thư giãn','Wi-Fi miễn phí','Trà thảo mộc mỗi ngày']},
 {id:'family',name:'Garden House',subtitle:'Bình yên, khi ở bên nhau.',image:'suite',gallery:['suite','cabin','room'],capacity:6,size:90,price:4200000,tag:'DÀNH CHO GIA ĐÌNH',description:'Ngôi nhà ấm áp với hai phòng ngủ, một khu vườn nhỏ và chỗ cho những câu chuyện dài.',long:'Garden House là ngôi nhà cho những chuyến đi có nhiều tiếng cười. Hai phòng ngủ riêng, phòng khách chung và khoảng vườn để cả nhà có thể quây quần. Từng góc nhỏ đều hướng đến một kỳ nghỉ giản dị: cùng ăn sáng, cùng đọc sách, cùng dành thời gian cho nhau.',amenities:['Hai phòng ngủ riêng','Khu vườn nhỏ','Bữa sáng cho 6 người','Phòng khách chung','Wi-Fi miễn phí','Góc trà & bếp nhỏ']}
];
const experiences=[
 {id:'forest-walk',image:'trail',label:'KẾT NỐI THIÊN NHIÊN',name:'Theo lối mòn, tìm bình yên',short:'Đi bộ dưới tán rừng. Hít một hơi thật sâu. Để những bộn bề ở lại phía sau.',text:'Không cần đi thật xa để thấy mình nhẹ hơn. Men theo con đường nhỏ dưới tán cây, lắng nghe tiếng lá và dừng lại bất cứ khi nào bạn muốn. Một buổi dạo rừng được gợi ý cho những ai đang tìm khoảng thời gian thật sự thuộc về mình.',time:'07:00 – 09:00',duration:'Khoảng 60 phút',note:'Lịch trình minh họa'},
 {id:'morning-tea',image:'tea',label:'THƯỞNG THỨC TỪNG KHOẢNH KHẮC',name:'Một tách trà, một sớm mai',short:'Trà ấm, sương sớm và một khoảng hiên không vội. Bắt đầu ngày mới theo cách của bạn.',text:'Ấm trà còn nóng, chiếc ghế ngoài hiên và cuốn sách bạn chưa đọc hết. Buổi trà sáng tại AN được hình dung như một lời mời sống chậm: nếm vị trà, ngắm màu trời và để bản thân không phải làm gì thêm.',time:'06:30 – 10:00',duration:'Theo nhịp của bạn',note:'Gợi ý trong kỳ nghỉ'},
 {id:'private-dinner',image:'dining',label:'HƯƠNG VỊ CỦA SỰ QUÂY QUẦN',name:'Bữa tối dưới ánh đèn ấm',short:'Những món ăn theo mùa, một bàn ăn riêng và thời gian dành trọn cho nhau.',text:'Kết thúc một ngày bằng bữa tối trong ánh đèn dịu, với nguyên liệu theo mùa và những câu chuyện không bị ngắt quãng. Trải nghiệm dùng bữa riêng có thể được ghi chú khi gửi yêu cầu đặt kỳ nghỉ mẫu.',time:'18:00 – 20:30',duration:'Khoảng 90 phút',note:'Đề xuất đặt trước'},
 {id:'slow-yoga',image:'yoga',label:'TRỞ VỀ VỚI CHÍNH MÌNH',name:'Chậm một nhịp, sâu một hơi',short:'Một buổi vận động nhẹ giữa không khí trong lành, dành cho cả người mới bắt đầu.',text:'Giãn cơ, thả lỏng vai và tập trung vào nhịp thở. Buổi yoga nhẹ được đưa vào concept để bạn có thêm lựa chọn cho một kỳ nghỉ cân bằng. Không đặt mục tiêu tập luyện, chỉ dành một khoảng lặng cho cơ thể.',time:'06:30 – 07:15',duration:'45 phút',note:'Trải nghiệm minh họa'}
];
const main=document.querySelector('main');
const money=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫';
const img=(name,alt,cls='',eager=false)=>`<img src="assets/${name}.jpg" alt="${alt}" class="${cls}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
const arrow='<span aria-hidden="true">↗</span>';
const icon=(kind='leaf')=>{const paths={leaf:'M20 4C10 3 3 8 5 16c2 7 14 5 15-12ZM5 20 15 10',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z',bed:'M3 18v3m18-3v3M3 18V6m18 12V9H3m0 5h18M6 9V6h6v3',cup:'M4 4h13v8a6 6 0 0 1-13 0V4Zm13 1h2a3 3 0 0 1 0 6h-2M3 21h16',wifi:'M2 8a17 17 0 0 1 20 0M5 12a12 12 0 0 1 14 0M8 16a6 6 0 0 1 8 0m-4 4h.01',check:'m5 12 4 4L19 6'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind]?`<path d="${paths[kind]}"/>`:`<path d="${paths.leaf}"/>`}</svg>`;};
const localToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
function datePlus(date,days){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+days);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
let bookingDraft={checkin:'',checkout:'',guests:'2',room:'forest'};
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function roomCard(r){return `<article class="room-card"><a class="room-image" href="#/phong/${r.id}" aria-label="Khám phá ${r.name}">${img(r.image,r.name+' — không gian nghỉ dưỡng minh họa')}<span class="room-tag">${r.tag}</span></a><div class="room-meta"><span>${r.size} m²</span><span aria-hidden="true">·</span><span>Tối đa ${r.capacity} khách</span><span aria-hidden="true">·</span><span>Hướng thiên nhiên</span></div><h3><a href="#/phong/${r.id}">${r.name}</a></h3><p class="room-description">${r.description}</p><div class="room-card-bottom"><span class="price">${money(r.price)} <small>/ đêm</small></span><a href="#/phong/${r.id}" class="circle-link" aria-label="Xem phòng ${r.name}">↗</a></div></article>`;}
function experienceCard(e){return `<a class="experience-card" href="#/trai-nghiem?section=${e.id}"><div class="image-wrap">${img(e.image,e.name)}</div><span class="eyebrow">${e.label}</span><h3>${e.name} <span aria-hidden="true">↗</span></h3><p>${e.short}</p></a>`;}
function invitation(){return `<section class="invitation"><div class="wrap"><div><span class="eyebrow">HẸN BẠN Ở MỘT NƠI THẬT AN</span><h2>Một kỳ nghỉ, thật sự nghỉ.</h2><p>Để lại những ồn ào. Mang theo một tâm hồn rộng mở.</p></div><a href="#/dat-phong" class="button">Lên lịch cho kỳ nghỉ ${arrow}</a></div></section>`;}
function home(){return `<section class="hero">${img('forest','Ánh nắng xuyên qua tán rừng xanh','hero-image',true)}<div class="hero-content wrap reveal"><span class="eyebrow">ẨN MÌNH GIỮA THIÊN NHIÊN</span><h1>Rời phố thị.<br>Về với <em>an yên.</em></h1><p class="hero-copy">Có một nơi, ngày bắt đầu bằng tiếng chim.<br>Và bạn chẳng cần vội vàng làm gì cả.</p><a href="#/phong" class="button light">Tìm chốn nghỉ của bạn ${arrow}</a></div><div class="hero-side">A LITTLE CLOSER TO NATURE</div><div class="hero-bottom"><span class="hero-location">${icon('pin')} GIỮA NHỮNG TẦNG XANH · AN RETREAT</span><a class="hero-scroll" href="#cau-chuyen">CHẬM LẠI MỘT CHÚT <span aria-hidden="true">↓</span></a></div></section>
 <form class="booking-bar wrap" id="quick-book"><div><label for="quick-in">Ngày nhận phòng</label><input id="quick-in" type="date" name="checkin" aria-label="Ngày nhận phòng" min="${localToday()}" required></div><div><label for="quick-out">Ngày trả phòng</label><input id="quick-out" type="date" name="checkout" aria-label="Ngày trả phòng" min="${datePlus(localToday(),1)}" required></div><div><label for="quick-guests">Số khách</label><select id="quick-guests" name="guests">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${n===2?'selected':''}>${n} người lớn</option>`).join('')}</select></div><button class="button" type="submit">Tìm không gian nghỉ ${arrow}</button></form>
 <section class="section wrap intro" id="cau-chuyen"><div class="intro-copy"><span class="eyebrow">CÂU CHUYỆN CỦA AN</span><h2>Không cần đi thật xa.<br>Chỉ cần <em>thấy thật an.</em></h2><p>Giữa những tán cây, AN được hình dung như một chốn trở về. Những căn nhà nhỏ nép mình vào rừng, đủ riêng tư để bạn lắng nghe thiên nhiên, đủ ấm áp để thấy mình được thuộc về.</p><p>Không lịch trình dày đặc. Không tiếng còi xe. Chỉ có nắng ghé qua hiên, một tách trà còn ấm và thời gian dành cho những điều giản dị.</p><a href="#/lien-he" class="text-link">Một chút về AN ${arrow}</a><div class="intro-index">an<small>/ LÀ BÌNH YÊN, LÀ TRỞ VỀ.</small></div></div><div class="intro-image">${img('cabin','Ngôi nhà giữa những tán cây — ảnh minh họa concept')}<div class="image-note">${icon('leaf')}<span>GẦN THIÊN NHIÊN HƠN.<br>GẦN CHÍNH MÌNH HƠN.</span></div></div></section>
 <section class="section room-section wrap"><div class="section-head"><div><span class="eyebrow">NHỮNG KHÔNG GIAN RIÊNG</span><h2>Mỗi căn nhà,<br>một khoảng <em>bình yên.</em></h2></div><a href="#/phong" class="text-link">Khám phá tất cả phòng ${arrow}</a></div><div class="room-grid">${rooms.map(roomCard).join('')}</div></section>
 <section class="manifesto">${img('trail','Tán rừng xanh yên tĩnh')}<div class="wrap"><span class="eyebrow">THE ART OF DOING NOTHING</span><h2>Đôi khi, điều tuyệt nhất<br>là <em>chẳng cần làm gì.</em></h2><p>Hít thở sâu hơn. Ngủ thêm một chút. Và cứ thế, thảnh thơi.</p></div></section>
 <section class="section wrap"><div class="section-head"><div><span class="eyebrow">NHỮNG NGÀY Ở AN</span><h2>Chậm một nhịp.<br><em>Chạm nhiều hơn.</em></h2></div><a href="#/trai-nghiem" class="text-link">Khám phá trải nghiệm ${arrow}</a></div><div class="experience-grid">${experiences.slice(0,3).map(experienceCard).join('')}</div></section>${invitation()}`;}

function roomsPage(params){const guests=params.get('guests')||'0';return `<div class="wrap rooms-page reveal"><div class="breadcrumb"><a href="#/">Trang chủ</a><span>/</span><span>Không gian nghỉ</span></div><div class="page-heading"><span class="eyebrow">TÌM CHỐN NGHỈ CỦA BẠN</span><h1>Một nơi, dành riêng<br>cho <em>sự thảnh thơi.</em></h1><p>Từ căn cabin cho hai người đến ngôi nhà cho cả gia đình. Mỗi không gian là một cách khác để tận hưởng những ngày giữa thiên nhiên.</p></div><form class="filters" id="room-filter"><div><label for="filter-guests">Bạn đi cùng bao nhiêu người?</label><select id="filter-guests" name="guests"><option value="0">Tất cả số khách</option>${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${guests===String(n)?'selected':''}>${n} khách</option>`).join('')}</select></div><div><label for="filter-budget">Ngân sách mỗi đêm</label><select id="filter-budget"><option value="0">Tất cả mức giá</option><option value="2000000">Đến 2.000.000 ₫</option><option value="3000000">Đến 3.000.000 ₫</option><option value="5000000">Đến 5.000.000 ₫</option></select></div><span class="result-count" id="result-count" aria-live="polite"></span></form><div class="room-grid" id="filtered-rooms"></div><p class="small-text" style="margin-top:35px">Giá minh họa cho dự án concept, bao gồm bữa sáng. Lọc theo sức chứa và ngân sách; chưa kiểm tra tình trạng phòng thực tế.</p></div>${invitation()}`;}

function detailPage(room){return `<div class="wrap reveal"><div class="breadcrumb"><a href="#/">Trang chủ</a><span>/</span><a href="#/phong">Không gian nghỉ</a><span>/</span><span>${room.name}</span></div><div class="page-heading"><span class="eyebrow">${room.size} M² · TỐI ĐA ${room.capacity} KHÁCH · KHÔNG GIAN RIÊNG</span><h1>${room.name}</h1><p>${room.subtitle}</p></div><div class="detail-gallery"><button data-photo="0" aria-label="Mở ảnh ${room.name}">${img(room.gallery[0],room.name,'',true)}</button><div class="gallery-stack"><button data-photo="1" aria-label="Xem ảnh không gian phòng">${img(room.gallery[1],'Không gian nghỉ và nội thất minh họa')}</button><button data-photo="2" aria-label="Xem ảnh thiên nhiên">${img(room.gallery[2],'Khung cảnh thiên nhiên và không gian minh họa')}</button></div><button class="view-photos" data-photo="0">Xem tất cả 3 ảnh ↗</button></div><div class="detail-layout"><div class="detail-copy"><span class="eyebrow">NGÀY BÌNH YÊN BẮT ĐẦU TỪ ĐÂY</span><h2 style="margin-top:18px">Ở lại một chút.<br><em>Thảnh thơi thêm một chút.</em></h2><p>${room.long}</p><h3>Những điều nhỏ, đủ đầy.</h3><div class="amenities">${room.amenities.map((a,i)=>`<span>${icon(['bed','leaf','cup','sun','wifi','cup'][i])}${a}</span>`).join('')}</div><details class="policy"><summary>Nhận & trả phòng</summary>Nhận phòng từ 14:00, trả phòng trước 12:00. Khung giờ mang tính minh họa cho concept.</details><details class="policy"><summary>Một vài lưu ý khi ở AN</summary>Không gian không khói thuốc. Giữ yên tĩnh sau 22:00. Không mang âm thanh lớn ra khu vực chung. Mọi nội dung là đề xuất thiết kế, chưa áp dụng cho cơ sở thực tế.</details></div><aside class="booking-card"><span class="eyebrow">KỲ NGHỈ CỦA BẠN</span><div class="price" style="margin-top:18px">${money(room.price)} <small>/ đêm</small></div><p>${room.size} m² · Tối đa ${room.capacity} khách</p><div class="included">✓ Bữa sáng đi kèm<br>✓ Không gian riêng tư<br>✓ Trà & cà phê trong phòng</div><a href="#/dat-phong?room=${room.id}" class="button">Chọn không gian này ${arrow}</a><p>Giá minh họa. Yêu cầu đặt phòng ở bước tiếp theo là mô phỏng.</p></aside></div></div>${invitation()}`;}

function experiencesPage(){return `<section class="experience-hero">${img('trail','Ánh sáng giữa những tán rừng','',true)}<div class="wrap reveal"><span class="eyebrow">NHỮNG NGÀY Ở AN</span><h1>Ít lịch trình hơn.<br><em>Nhiều cảm nhận hơn.</em></h1><p>Không cần lấp đầy một ngày. Chỉ cần chọn những điều khiến bạn thấy vui và thật sự có mặt trong khoảnh khắc ấy.</p></div></section><div class="wrap experience-list">${experiences.map((e,i)=>`<article class="experience-row" id="${e.id}"><div class="experience-visual">${img(e.image,e.name)}</div><div><span class="eyebrow">0${i+1} / ${e.label}</span><h2>${e.name}</h2><p>${e.text}</p><a href="#/dat-phong?experience=${e.id}" class="text-link">Thêm vào kỳ nghỉ của bạn ${arrow}</a><div class="experience-facts"><span>${e.time}</span><span>${e.duration}</span><span>${e.note}</span></div></div></article>`).join('')}</div>${invitation()}`;}

function field(name,label,type='text',extra=''){return `<div class="field ${extra}"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" ${['checkin','checkout'].includes(name)?`min="${localToday()}"`:''} ${name==='phone'?'autocomplete="tel"':name==='name'?'autocomplete="name"':name==='email'?'autocomplete="email"':''} required aria-describedby="error-${name}"><span class="field-error" id="error-${name}"></span></div>`;}
function bookingPage(params){const selected=rooms.find(r=>r.id===(params.get('room')||bookingDraft.room))||rooms[0];bookingDraft.room=selected.id;return `<div class="wrap reveal"><div class="breadcrumb"><a href="#/">Trang chủ</a><span>/</span><span>Đặt kỳ nghỉ</span></div><div class="page-heading"><span class="eyebrow">HẸN BẠN Ở AN</span><h1>Kỳ nghỉ của bạn,<br>bắt đầu <em>từ đây.</em></h1><p>Chọn một khoảng thời gian và không gian bạn yêu thích. Đây là form trải nghiệm mẫu, thông tin không được gửi đi.</p></div><div id="booking-content" class="booking-layout"><form id="booking-form" class="booking-form" novalidate><h2 class="form-subheading">01. Kỳ nghỉ bạn mong chờ</h2><div class="field full"><label for="room-select">Không gian nghỉ</label><select id="room-select" name="room">${rooms.map(r=>`<option value="${r.id}" ${r.id===selected.id?'selected':''}>${r.name} · tối đa ${r.capacity} khách</option>`).join('')}</select></div>${field('checkin','Ngày nhận phòng','date')}${field('checkout','Ngày trả phòng','date')}<div class="field full"><label for="guests">Số khách</label><select id="guests" name="guests" aria-describedby="error-guests">${[1,2,3,4,5,6].map(n=>`<option value="${n}">${n} khách</option>`).join('')}</select><span class="field-error" id="error-guests"></span></div><h2 class="form-subheading">02. Một chút về bạn</h2>${field('name','Họ và tên','text','full')}${field('email','Địa chỉ email','email','mobile-full')}${field('phone','Số điện thoại','tel','mobile-full')}<div class="field full"><label for="notes">Điều bạn muốn nhắn với AN <span class="small-text">(không bắt buộc)</span></label><textarea id="notes" name="notes" placeholder="Một dịp đặc biệt, trải nghiệm yêu thích, hay điều khiến kỳ nghỉ của bạn trọn vẹn hơn…"></textarea></div><p class="form-note">Dự án concept portfolio: thao tác này chỉ tạo xác nhận trên trình duyệt. Không gửi email, không giữ phòng và không thu phí.</p><div class="form-actions"><button type="submit" class="button">Gửi yêu cầu mẫu ${arrow}</button></div></form><aside id="booking-summary" class="booking-summary" aria-label="Tóm tắt kỳ nghỉ"></aside></div></div>`;}

function contactPage(){return `<div class="wrap reveal"><div class="breadcrumb"><a href="#/">Trang chủ</a><span>/</span><span>Câu chuyện & liên hệ</span></div><div class="page-heading"><span class="eyebrow">CHÀO BẠN, ĐÂY LÀ AN</span><h1>Một chốn trở về.<br>Một chút <em>an nhiên.</em></h1></div><div class="contact-grid">${img('cabin','Kiến trúc hòa vào thiên nhiên — ảnh concept minh họa')}<div><h2>AN là một ý tưởng<br>về <em>cách nghỉ ngơi.</em></h2><p>Một ngôi nhà giữa rừng. Những điều giản dị được chăm chút. Một nơi giúp chúng ta rời màn hình, gần thiên nhiên và gần nhau hơn.</p><p>Website này được xây dựng để minh họa cách một thương hiệu nghỉ dưỡng có thể kể câu chuyện của mình: qua hình ảnh, qua từng không gian và qua một hành trình đặt kỳ nghỉ rõ ràng, dễ sử dụng.</p><div class="concept-box"><strong>Đây là dự án concept portfolio.</strong>AN Retreat là thương hiệu giả định. Chưa có cơ sở lưu trú, địa chỉ hay số điện thoại hoạt động. Hình ảnh được dùng để diễn tả phong cách; các ảnh không đại diện cho cùng một địa điểm. Giá và trải nghiệm đều mang tính minh họa.</div><span class="eyebrow">TRẢI NGHIỆM LUỒNG LIÊN HỆ</span><p>Bạn có thể dùng form đặt kỳ nghỉ để thử gửi yêu cầu và ghi chú. Thông tin chỉ được xử lý trong phiên xem trên trình duyệt.</p><a href="#/dat-phong" class="button">Thử form đặt kỳ nghỉ ${arrow}</a></div></div></div>${invitation()}`;}

function wireHome(){const form=document.querySelector('#quick-book');if(!form)return;form.checkin.value=bookingDraft.checkin;form.checkout.value=bookingDraft.checkout;form.guests.value=bookingDraft.guests;form.checkin.addEventListener('change',()=>{const min=datePlus(form.checkin.value||localToday(),1);form.checkout.min=min;if(form.checkout.value&&form.checkout.value<min)form.checkout.value=min;});form.addEventListener('submit',e=>{e.preventDefault();bookingDraft={...bookingDraft,...Object.fromEntries(new FormData(form))};location.hash='/phong?guests='+bookingDraft.guests;});document.querySelector('.hero-scroll')?.addEventListener('click',e=>{e.preventDefault();document.querySelector('#cau-chuyen').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});}
function wireRooms(){const filters=document.querySelector('#room-filter');if(!filters)return;document.querySelector('#filter-budget').value=new URLSearchParams(location.hash.split('?')[1]||'').get('budget')||'0';const update=(persist=false)=>{if(persist){const guests=document.querySelector('#filter-guests').value;const budget=document.querySelector('#filter-budget').value;history.replaceState(null,'','#/phong?guests='+guests+'&budget='+budget);if(Number(guests)>0)bookingDraft.guests=guests;}const list=filterRooms(rooms,document.querySelector('#filter-guests').value,document.querySelector('#filter-budget').value);document.querySelector('#result-count').textContent=`${list.length} không gian phù hợp`;document.querySelector('#filtered-rooms').innerHTML=list.length?list.map(roomCard).join(''):`<div class="empty-state"><h3>Chưa có không gian phù hợp.</h3><p>Thử thay đổi số khách hoặc tăng ngân sách để khám phá thêm lựa chọn.</p><button type="button" class="button outline" id="reset-filters">Xóa bộ lọc ↗</button></div>`;document.querySelector('#reset-filters')?.addEventListener('click',()=>{filters.reset();document.querySelector('#filter-guests').value='0';update(true);});};filters.addEventListener('change',update);filters.addEventListener('submit',e=>e.preventDefault());update();}

let galleryRoom;let galleryIndex=0;const dialog=document.querySelector('#gallery-dialog');
function showGalleryImage(){const name=galleryRoom.gallery[galleryIndex];document.querySelector('#gallery-image').src=`assets/${name}.jpg`;document.querySelector('#gallery-image').alt=`${galleryRoom.name} — ảnh minh họa ${galleryIndex+1}`;document.querySelector('#gallery-position').textContent=`${galleryIndex+1} / ${galleryRoom.gallery.length}`;}
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
document.querySelector('#gallery-prev').addEventListener('click',()=>{galleryIndex=(galleryIndex+galleryRoom.gallery.length-1)%galleryRoom.gallery.length;showGalleryImage();});
document.querySelector('#gallery-next').addEventListener('click',()=>{galleryIndex=(galleryIndex+1)%galleryRoom.gallery.length;showGalleryImage();});
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight')document.querySelector('#gallery-next').click();if(e.key==='ArrowLeft')document.querySelector('#gallery-prev').click();});
function wireGallery(room){document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{galleryRoom=room;galleryIndex=Number(b.dataset.photo);showGalleryImage();dialog.showModal();}));}

function wireBooking(params){const form=document.querySelector('#booking-form');if(!form)return;for(const key of ['checkin','checkout','guests','name','email','phone','notes'])form.elements[key].value=bookingDraft[key]||'';if(params.get('experience')&&!form.notes.value){const exp=experiences.find(e=>e.id===params.get('experience'));if(exp)form.notes.value=`Tôi quan tâm trải nghiệm: ${exp.name}.`;}
 const update=()=>{const values=Object.fromEntries(new FormData(form));bookingDraft={...bookingDraft,...values};const room=rooms.find(r=>r.id===values.room);const {nights,total}=bookingSummary(room,values.checkin,values.checkout);const min=datePlus(values.checkin||localToday(),1);form.checkout.min=min;document.querySelector('#booking-summary').innerHTML=`${img(room.image,room.name+' — ảnh minh họa')}<span class="eyebrow">KHOẢNG RIÊNG CỦA BẠN</span><h3>${room.name}</h3><p class="small-text">${room.size} m² · Tối đa ${room.capacity} khách</p><div class="summary-row"><span>Giá minh họa / đêm</span><strong>${money(room.price)}</strong></div><div class="summary-row"><span>Thời gian lưu trú</span><span>${nights?nights+' đêm':'Chưa chọn ngày'}</span></div><div class="summary-row"><span>Bữa sáng</span><span>Đã bao gồm</span></div><div class="summary-row total"><span>Tạm tính</span><span>${nights?money(total):'—'}</span></div><p class="summary-note">Giá mẫu theo số đêm, chưa phải báo giá thực tế. Không có thanh toán trong bản demo này.</p>`;};
 form.addEventListener('input',update);form.addEventListener('change',update);update();
 form.addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));const room=rooms.find(r=>r.id===values.room);const errors=validateBooking(values,room,localToday());for(const name of ['name','email','phone','checkin','checkout','guests']){document.querySelector('#error-'+name).textContent=errors[name]||'';form.elements[name].setAttribute('aria-invalid',String(Boolean(errors[name])));}const first=Object.keys(errors)[0];if(first){form.elements[first].focus();return;}const summary=bookingSummary(room,values.checkin,values.checkout);const container=document.querySelector('#booking-content');container.className='';container.innerHTML=`<section class="success-panel" role="status" tabindex="-1"><div class="success-mark" aria-hidden="true">✓</div><span class="eyebrow">ĐÃ HOÀN TẤT TRẢI NGHIỆM MẪU</span><h2 style="margin-top:18px">Một kỳ nghỉ thật an,<br><em>đang chờ trong ý tưởng.</em></h2><p>Cảm ơn ${escapeHTML(values.name.trim())}. Bạn vừa hoàn tất luồng yêu cầu đặt phòng mô phỏng.</p><div class="summary-row"><span>Không gian</span><strong>${room.name}</strong></div><div class="summary-row"><span>Ngày lưu trú</span><span>${escapeHTML(values.checkin)} → ${escapeHTML(values.checkout)}</span></div><div class="summary-row"><span>${Number(values.guests)} khách · ${summary.nights} đêm</span><strong>${money(summary.total)}</strong></div><p style="margin-top:23px"><strong>Chưa có yêu cầu nào được gửi đi.</strong> Không có email xác nhận, đặt phòng thực tế hay khoản thu nào phát sinh.</p><a href="#/phong" class="button">Khám phá không gian khác ${arrow}</a></section>`;container.querySelector('.success-panel').focus();container.scrollIntoView({block:'start'});});}

const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('nav');
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Đóng menu':'Mở menu');nav.classList.toggle('open',open);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');}});
function render(){const raw=location.hash.slice(1)||'/';const [path,query='']=raw.split('?');const params=new URLSearchParams(query);let key='home';let title='Một khoảng lặng giữa rừng';let room;let html;
 if(path==='/'||path===''){html=home();}
 else if(path==='/phong'){key='rooms';title='Không gian nghỉ';html=roomsPage(params);}
 else if(path.startsWith('/phong/')){key='rooms';room=rooms.find(r=>r.id===path.split('/')[2]);if(room){title=room.name;html=detailPage(room);}else html='<section class="wrap not-found"><h1>Không tìm thấy không gian này.</h1><a class="button" href="#/phong">Về danh sách phòng ↗</a></section>';}
 else if(path==='/trai-nghiem'){key='experiences';title='Những ngày ở AN';html=experiencesPage();}
 else if(path==='/dat-phong'){key='booking';title='Đặt kỳ nghỉ';html=bookingPage(params);}
 else if(path==='/lien-he'){key='contact';title='Câu chuyện & liên hệ';html=contactPage();}
 else{key='notfound';html='<section class="wrap not-found"><h1>Lối nhỏ này chưa có trên bản đồ.</h1><a class="button" href="#/">Trở về AN ↗</a></section>';}
 document.body.classList.toggle('inner-page',key!=='home');main.innerHTML=html;document.title=`AN Retreat — ${title}`;
 document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===key)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Mở menu');if(dialog.open)dialog.close();
 wireHome();wireRooms();if(room)wireGallery(room);wireBooking(params);
 window.scrollTo({top:0,behavior:'instant'});if(params.get('section'))requestAnimationFrame(()=>document.getElementById(params.get('section'))?.scrollIntoView());
}
const scrollPositions=new Map();window.addEventListener('hashchange',event=>{scrollPositions.set(event.oldURL,window.scrollY);render();if(scrollPositions.has(location.href))window.scrollTo({top:scrollPositions.get(location.href),behavior:'instant'});main.focus({preventScroll:true});});render();
